wd_proto.fields = {
    f_magic,
    f_version,
    f_flags,
    f_flags__on_trip,
    f_asset,
    f_trip,
    f_records,
    f_records__tag,
    f_records__length,
    f_records__value,
    f_records__value__latitude,
    f_records__value__longitude,
    f_records__value__heading,
    f_records__value__note,
    f_records__value__manifest,
    f_records__value__data,
}

-- The Fields the Info column shows, extracted from each packet once it is read
local x_asset = Field.new("tracker.asset")

-- The ProtoFields of each use of a Type, passed to the Type's dissect function
local site_records = {
    path = "records",
    f_tag = f_records__tag,
    f_length = f_records__length,
    f_value = f_records__value,
    f_value__latitude = f_records__value__latitude,
    f_value__longitude = f_records__value__longitude,
    f_value__heading = f_records__value__heading,
    f_value__note = f_records__value__note,
    f_value__manifest = f_records__value__manifest,
    f_value__data = f_records__value__data,
}

local wd_ei_truncated = wd_expert_truncated("tracker")
local wd_ei_invalid = wd_expert_invalid("tracker")
local wd_ei_unexpected = wd_expert_unexpected("tracker")
local wd_ei_dissector = wd_expert_dissector("tracker")
wd_proto.experts = { wd_ei_truncated, wd_ei_invalid, wd_ei_unexpected, wd_ei_dissector }

-- Type: Record
local function dissect_Record(tvb, pinfo, tree, offset, site)
    local v_length, v_tag
    -- Field: tag
    if not wd_fits(tvb, offset, 1) then
        wd_truncated(tree, wd_ei_truncated, site.path .. ".tag")
        return nil
    end
    tree:add(site.f_tag, tvb(offset, 1))
    v_tag = string.unpack(">I1", tvb:raw(offset, 1))
    offset = offset + 1
    -- Field: length
    if not wd_fits(tvb, offset, 1) then
        wd_truncated(tree, wd_ei_truncated, site.path .. ".length")
        return nil
    end
    tree:add(site.f_length, tvb(offset, 1)):set_hidden(true)
    v_length = string.unpack(">I1", tvb:raw(offset, 1))
    offset = offset + 1
    -- Switch: value
    do
        local subject = v_tag
        local start = offset
        local tree = tree:add(site.f_value, tvb(offset, tvb:len() - offset))
        tree:append_text(": " .. wd_case_name(names_value, subject))
        if subject == 1 then
            -- Field: value.latitude
            if not wd_fits(tvb, offset, 4) then
                wd_truncated(tree, wd_ei_truncated, site.path .. ".value.latitude")
                return nil
            end
            tree:add(site.f_value__latitude, tvb(offset, 4))
            offset = offset + 4
            -- Field: value.longitude
            if not wd_fits(tvb, offset, 4) then
                wd_truncated(tree, wd_ei_truncated, site.path .. ".value.longitude")
                return nil
            end
            tree:add(site.f_value__longitude, tvb(offset, 4))
            offset = offset + 4
        elseif subject == 2 then
            -- Field: value.heading
            if not wd_fits(tvb, offset, 2) then
                wd_truncated(tree, wd_ei_truncated, site.path .. ".value.heading")
                return nil
            end
            do
                local item = tree:add(site.f_value__heading, tvb(offset, 2))
                local value = string.unpack(">I2", tvb:raw(offset, 2))
                wd_expect(item, value, { 0, 359 }, "0-359", wd_ei_unexpected, site.path .. ".value.heading")
            end
            offset = offset + 2
        elseif subject == 3 then
            -- Field: value.note
            do
                local len = v_length
                if len < 0 then
                    wd_invalid(tree, wd_ei_invalid, "size " .. len .. " is negative", site.path .. ".value.note")
                    return nil
                end
                if not wd_fits(tvb, offset, len) then
                    wd_truncated(tree, wd_ei_truncated, site.path .. ".value.note")
                    return nil
                end
                tree:add_packet_field(site.f_value__note, tvb(offset, len), ENC_UTF_8)
                offset = offset + len
            end
        elseif subject == 4 then
            -- Field: value.manifest
            do
                local len = v_length
                if len < 0 then
                    wd_invalid(tree, wd_ei_invalid, "size " .. len .. " is negative", site.path .. ".value.manifest")
                    return nil
                end
                if not wd_fits(tvb, offset, len) then
                    wd_truncated(tree, wd_ei_truncated, site.path .. ".value.manifest")
                    return nil
                end
                tree:add(site.f_value__manifest, tvb(offset, len))
                wd_handoff("json", tvb(offset, len), pinfo, tree, wd_ei_dissector, site.path .. ".value.manifest")
                offset = offset + len
            end
        else
            -- Field: value.data
            do
                local len = v_length
                if len < 0 then
                    wd_invalid(tree, wd_ei_invalid, "size " .. len .. " is negative", site.path .. ".value.data")
                    return nil
                end
                if not wd_fits(tvb, offset, len) then
                    wd_truncated(tree, wd_ei_truncated, site.path .. ".value.data")
                    return nil
                end
                tree:add(site.f_value__data, tvb(offset, len))
                offset = offset + len
            end
        end
        tree:set_len(offset - start)
    end
    -- Padding
    do
        local len, fault = wd_evaluate(function() return wd_mod(wd_sub(4, wd_mod(wd_add(v_length, 2), 4)), 4) end)
        if not len then
            wd_invalid(tree, wd_ei_invalid, fault, "Padding in " .. site.path)
            return nil
        end
        if len < 0 then
            wd_invalid(tree, wd_ei_invalid, "padding " .. len .. " is negative", "Padding in " .. site.path)
            return nil
        end
        if not wd_fits(tvb, offset, len) then
            wd_truncated(tree, wd_ei_truncated, "Padding in " .. site.path)
            return nil
        end
        tree:add(tvb(offset, len), "Padding")
        offset = offset + len
    end
    return offset
end

-- Layout
local function dissect_top(tvb, pinfo, tree, offset)
    local v_flags
    -- Field: magic
    if not wd_fits(tvb, offset, 2) then
        wd_truncated(tree, wd_ei_truncated, "magic")
        return nil
    end
    do
        local item = tree:add(f_magic, tvb(offset, 2))
        item:set_hidden(true)
        local value = string.unpack(">I2", tvb:raw(offset, 2))
        wd_expect(item, value, { 16724, 16724 }, "0x4154", wd_ei_unexpected, "magic")
    end
    offset = offset + 2
    -- Field: version
    if not wd_fits(tvb, offset, 1) then
        wd_truncated(tree, wd_ei_truncated, "version")
        return nil
    end
    do
        local item = tree:add(f_version, tvb(offset, 1))
        local value = string.unpack(">I1", tvb:raw(offset, 1))
        wd_expect(item, value, { 1, 1 }, "1", wd_ei_unexpected, "version")
    end
    offset = offset + 1
    -- Field: flags
    if not wd_fits(tvb, offset, 1) then
        wd_truncated(tree, wd_ei_truncated, "flags")
        return nil
    end
    do
        local item = tree:add(f_flags, tvb(offset, 1))
        item:add(f_flags__on_trip, tvb(offset, 1))
    end
    v_flags = string.unpack(">I1", tvb:raw(offset, 1))
    offset = offset + 1
    -- Field: asset
    if not wd_fits(tvb, offset, 2) then
        wd_truncated(tree, wd_ei_truncated, "asset")
        return nil
    end
    tree:add(f_asset, tvb(offset, 2))
    offset = offset + 2
    -- If: trip
    do
        local condition = wd_band(wd_shr(v_flags, 7), 1)
        if condition ~= 0 then
            -- Field: trip
            if not wd_fits(tvb, offset, 4) then
                wd_truncated(tree, wd_ei_truncated, "trip")
                return nil
            end
            tree:add(f_trip, tvb(offset, 4))
            offset = offset + 4
        end
    end
    -- Field: records
    do
        local i = 0
        while offset < tvb:len() do
            local start = offset
            local tree = tree:add(f_records, tvb(offset, tvb:len() - offset))
            tree:append_text(" [" .. i .. "]")
            offset = dissect_Record(tvb, pinfo, tree, offset, site_records)
            if not offset then
                return nil
            end
            tree:set_len(offset - start)
            if offset == start then
                wd_invalid(tree, wd_ei_invalid, "element " .. i .. " is empty", "records")
                return nil
            end
            i = i + 1
        end
    end
    return offset
end

function wd_proto.dissector(tvb, pinfo, tree)
    pinfo.cols.protocol = "TRACKER"
    local before = wd_info_counts({ x_asset })
    local root = tree:add(wd_proto, tvb(0, tvb:len()), "Asset Tracker")
    dissect_top(tvb, pinfo, root, 0)
    pinfo.cols.info = "Asset " .. wd_info_display(x_asset, before)
    return tvb:len()
end

-- Registration
wd_proto.prefs.udp_ports = Pref.range("UDP port(s)", "47300", "The UDP ports decoded as TRACKER", 65535)
wd_register_ports(wd_proto, { { "udp_ports", "udp.port" } })

-- Decode As
DissectorTable.get("udp.port"):add_for_decode_as(wd_proto)
DissectorTable.get("tcp.port"):add_for_decode_as(wd_proto)
